"""Generate the Supplementary Tables (LaTeX) directly from fe_data.py so that no value is re-typed by hand.
Usage: python supp_tables.py ..\\..\\supp_tables.tex   (run from scripts/analysis, or use scripts/make_figures.bat)"""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "figsrc"))   # figstyle, fe_data
import statistics as st
sys.path.insert(0, os.path.dirname(__file__))
from fe_data import *

OUT = sys.argv[1] if len(sys.argv) > 1 else "supp_tables.tex"
L = ["% !TEX root = supplementary.tex",
     "% Generated by scripts/analysis/supp_tables.py from fe_data.py -- edit the script, not this file."]
w = L.append

def f4(v):
    return "--" if v is None else f"{v:.4f}"

def pct(v, ref):
    if v is None or ref is None:
        return "--"
    d = 100 * (v - ref) / ref
    return f"{d:+.1f}".replace("-", "$-$")

def ints(n):
    return f"{n:,}"

METRICS = [("ant", "Anterior facet"), ("mid", "Middle facet"), ("post", "Posterior facet")]
ROWS = []
for k, name in METRICS:
    for s in ["max", "min", "mean"]:
        ROWS.append((f"{k}_{s}", f"{name}, {s}"))
ROWS += [("tn_max", "Talonavicular, max"), ("cc_max", "Calcaneocuboid, max"), ("tc_max", "Talocalcaneal complex, max")]
SHORT = {"ant_max": "Ant max", "ant_min": "Ant min", "ant_mean": "Ant mean", "mid_max": "Mid max", "mid_min": "Mid min",
         "mid_mean": "Mid mean", "post_max": "Post max", "post_min": "Post min", "post_mean": "Post mean",
         "tn_max": "TN max", "cc_max": "CC max", "tc_max": "TC max"}

# ---------------------------------------------------------------- Table 1
w(r"\begin{table}[p]\centering\footnotesize")
w(r"\caption{\textbf{Models of the finite element atlas.} All models share the template geometry, materials, contacts, "
  r"loads and constraints and differ only in the condition listed. Element and node counts are from the FE reports. "
  r"The neutral-alignment conditions of types I--IV are the type models of the coalition series, so the 12 alignment "
  r"conditions require 8 additional models. The first intact mesh was superseded as reference by the re-meshed intact "
  r"model (Supplementary Note~2).}")
w(r"\label{stab:models}")
w(r"\begin{tabular}{@{}llllrr@{}}\toprule")
w(r"Series & Model & Condition & Report & Elements & Nodes\\\midrule")
def row(series, model, cond, rep, key):
    e, n = MESH[key]
    w(f"{series} & {model} & {cond} & {rep} & {ints(e)} & {ints(n)}\\\\")
row("Template", "Intact, first mesh", "first modeling round; validation", "1", "Normal (series 1)")
row("Reference", "Intact, re-meshed", "reference for all comparisons", "2, 3", "Normal (defect series)")
w(r"\addlinespace")
for i, nm in enumerate(["I", "II", "III", "IV", "V"]):
    cond = ["linear middle-facet", "linear with posterior hook", "shingled", "complete osseous middle-facet",
            "posterior-facet"][i]
    row("Coalition" if i == 0 else "", f"Rozansky {nm}", cond, "1, 3", f"Roz {nm}")
for i, nm in enumerate(["I", "II", "III", "IV"]):
    cond = ["middle-facet", "posterior-facet", "extra-articular", "complex"][i]
    row("", f"Type {nm}", cond + " (neutral alignment)", "1, 3", f"Type {nm}")
row("", "Complete fusion", "all talocalcaneal facets fused", "3", "Fusion")
w(r"\addlinespace")
first = True
for nm in ["I", "II", "III", "IV"]:
    for pos in ["varus", "valgus"]:
        row("Malalignment" if first else "", f"Type {nm}", f"10$^\\circ$ hindfoot {pos}", "3", f"Type {nm} {pos}")
        first = False
w(r"\addlinespace")
first = True
for fac, lab in [("Mid", "middle"), ("Post", "posterior")]:
    for d in DEFECTS[1:]:
        row("Facet defect" if first else "", f"{lab.capitalize()} {d}\\%", f"{d}\\% of the {lab} facet removed", "2",
            f"{fac} {d}")
        first = False
w(r"\bottomrule\end{tabular}")
w(r"\end{table}")
w("")

# ---------------------------------------------------------------- Table 2 (landscape)
w(r"\begin{landscape}")
w(r"\begin{table}[p]\centering\footnotesize")
w(r"\caption{\textbf{Coalition series: von Mises stress (MPa).} Maximum, minimum and mean over each articular surface and "
  r"maximum over the talocalcaneal complex (bridge region in coalition models). Intact = re-meshed intact reference. "
  r"Complete fusion has no subtalar facets (--). Values from the consolidated table of the final FE report.}")
w(r"\label{stab:coalition}")
w(r"\setlength{\tabcolsep}{4pt}")
w(r"\begin{tabular}{@{}l" + "r" * 11 + r"@{}}\toprule")
heads = ["Intact", "Roz I", "Roz II", "Roz III", "Roz IV", "Roz V", "Type I", "Type II", "Type III", "Type IV", "Fusion"]
w("Region, statistic & " + " & ".join(heads) + r"\\\midrule")
for k, lab in ROWS:
    w(lab + " & " + " & ".join(f4(v) for v in CLS[k]) + r"\\")
    if k in ("ant_mean", "mid_mean", "post_mean"):
        w(r"\addlinespace")
w(r"\addlinespace\midrule")
w(r"\multicolumn{12}{@{}l}{\emph{Talocalcaneal peak relative to the intact joint}}\\")
w(r"Ratio to intact & " + " & ".join(f"{v / CLS['tc_max'][0]:.2f}" for v in CLS["tc_max"]) + r"\\")
w(r"\bottomrule\end{tabular}")
w(r"\end{table}")
w(r"\end{landscape}")
w("")

# ---------------------------------------------------------------- Table 3 (landscape)
w(r"\begin{landscape}")
w(r"\begin{table}[p]\centering\footnotesize")
w(r"\caption{\textbf{Alignment series: von Mises stress (MPa) and change versus neutral alignment.} Ant, mid, post: anterior, "
  r"middle and posterior subtalar facets; TN, talonavicular; CC, calcaneocuboid; TC, talocalcaneal complex (coalition). "
  r"Malalignment of 10$^\circ$ was produced by repositioning the calcaneus relative to the tibial axis. Values from the "
  r"consolidated table of the final FE report. $^\dagger$The solver input of these two models contained material errors (type "
  r"III valgus: all cartilage had the properties of cancellous bone, 100~MPa and 0.3; type IV valgus: the cortical and cancellous "
  r"moduli of the fibula were interchanged); they are listed for completeness and are not analyzed (Methods).}")
w(r"\label{stab:alignment}")
w(r"\setlength{\tabcolsep}{3.2pt}")
keys = [k for k, _ in ROWS]
w(r"\begin{tabular}{@{}ll" + "r" * len(keys) + r"@{}}\toprule")
w("Type & Alignment & " + " & ".join(SHORT[k] for k in keys) + r"\\\midrule")
w(r"\multicolumn{" + str(2 + len(keys)) + r"}{@{}l}{\emph{a, Absolute values (MPa)}}\\")
BAD = {("Type III", 2), ("Type IV", 2)}      # solver input with material errors (2026-10-31); not analyzed
mark = lambda t, p: "$^\\dagger$" if (t, p) in BAD else ""
for t in ALIGN_TYPES:
    for p, pn in enumerate(["neutral", "10$^\\circ$ varus", "10$^\\circ$ valgus"]):
        w((t if p == 0 else "") + " & " + pn + mark(t, p) + " & " + " & ".join(f4(ALIGN[t][k][p]) for k in keys) + r"\\")
    w(r"\addlinespace")
w(r"\midrule")
w(r"\multicolumn{" + str(2 + len(keys)) + r"}{@{}l}{\emph{b, Change versus neutral alignment (\%)}}\\")
for t in ALIGN_TYPES:
    for p, pn in [(1, "10$^\\circ$ varus"), (2, "10$^\\circ$ valgus")]:
        w((t if p == 1 else "") + " & " + pn + mark(t, p) + " & " + " & ".join(pct(ALIGN[t][k][p], ALIGN[t][k][0]) for k in keys) + r"\\")
    w(r"\addlinespace")
w(r"\bottomrule\end{tabular}")
w(r"\end{table}")
w(r"\end{landscape}")
w("")

# ---------------------------------------------------------------- Tables 4, 5
def defect_table(D, facet, label, extra):
    w(r"\begin{table}[p]\centering\footnotesize")
    w(r"\caption{\textbf{" + facet.capitalize() + r"-facet defect series: von Mises stress (MPa) and change versus the intact "
      r"joint.} Each defect (percentage of facet area removed from the intact joint) represents the defect left by complete "
      r"resection of a coalition of that size; it never represents partial resection. All 15 models of the defect series "
      r"(intact reference and 14 defects) were meshed with identical controls (329,456--330,903 elements). " + extra + r"}")
    w(r"\label{" + label + "}")
    w(r"\setlength{\tabcolsep}{4.5pt}")
    w(r"\begin{tabular}{@{}l" + "r" * len(DEFECTS) + r"@{}}\toprule")
    w("Region, statistic & " + " & ".join(("Intact" if d == 0 else f"{d}\\%") for d in DEFECTS) + r"\\\midrule")
    w(r"\multicolumn{" + str(1 + len(DEFECTS)) + r"}{@{}l}{\emph{a, Absolute values (MPa)}}\\")
    for k, lab in ROWS:
        w(lab + " & " + " & ".join(f4(v) for v in D[k]) + r"\\")
    w(r"\midrule")
    w(r"\multicolumn{" + str(1 + len(DEFECTS)) + r"}{@{}l}{\emph{b, Change versus intact joint (\%)}}\\")
    for k, lab in ROWS:
        w(lab + " & -- & " + " & ".join(pct(v, D[k][0]) for v in D[k][1:]) + r"\\")
    w(r"\bottomrule\end{tabular}")
    w(r"\end{table}")
    w("")

defect_table(MID, "middle", "stab:mid",
             r"The residual middle-facet peak is maximal at 30\% (+43.8\%) and then falls, while the anterior-facet peak rises monotonically.")
inc = [100 * (POST["post_mean"][i] - POST["post_mean"][0]) / POST["post_mean"][0] for i in range(len(DEFECTS))]
steps = ", ".join(f"{inc[i] - inc[i - 1]:.1f}" for i in range(3, 6))
defect_table(POST, "posterior", "stab:post",
             r"The residual posterior-facet mean rises by " + steps +
             r" percentage points per additional 10\% between 20\% and 50\% and accelerates beyond 50\%.")

# ---------------------------------------------------------------- Table 6 separability
w(r"\begin{table}[p]\centering\footnotesize")
w(r"\caption{\textbf{Mechanical separability of the two coalition taxonomies.} \textbf{a}, Types ranked by peak "
  r"talocalcaneal (coalition) stress with the gap to the next type. \textbf{b}, Coefficient of variation (sample standard "
  r"deviation/mean) of each articular peak across the types of each taxonomy; a larger value indicates that the types load "
  r"the joint differently. \textbf{c}, Articular fingerprints: peak stress as a percentage of the intact joint. "
  r"Definitions in Supplementary Note~3.}")
w(r"\label{stab:separability}")
w(r"\setlength{\tabcolsep}{5pt}")
roz = list(range(1, 6)); ana = list(range(6, 10))
def ranked(idx):
    r = sorted(idx, key=lambda i: CLS["tc_max"][i])
    out = []
    for j, i in enumerate(r):
        gap = CLS["tc_max"][r[j + 1]] - CLS["tc_max"][i] if j + 1 < len(r) else None
        out.append((CLS_MODELS[i].replace("Roz", "Rozansky"), CLS["tc_max"][i], gap))
    return out
w(r"\begin{tabular}{@{}lrr@{\hspace{2.2em}}lrr@{}}\toprule")
w(r"\multicolumn{3}{@{}l}{\emph{a, Rozansky types}} & \multicolumn{3}{l}{\emph{a, Anatomy-based types}}\\")
w(r"Type & TC peak (MPa) & Gap to next & Type & TC peak (MPa) & Gap to next\\\midrule")
R, A = ranked(roz), ranked(ana)
for j in range(max(len(R), len(A))):
    left = f"{R[j][0]} & {R[j][1]:.2f} & {'--' if R[j][2] is None else f'{R[j][2]:.2f}'}" if j < len(R) else " & & "
    right = f"{A[j][0]} & {A[j][1]:.2f} & {'--' if A[j][2] is None else f'{A[j][2]:.2f}'}" if j < len(A) else " & & "
    w(left + " & " + right + r"\\")
gR = min(g for _, _, g in R if g is not None); gA = min(g for _, _, g in A if g is not None)
w(r"\midrule")
w(f"Minimum gap & & {gR:.2f} & Minimum gap & & {gA:.2f}" + r"\\")
w(r"\bottomrule\end{tabular}")
w(r"\par\vspace{1.2em}")
w(r"\begin{tabular}{@{}lrrrrrr@{}}\toprule")
w(r"\multicolumn{7}{@{}l}{\emph{b, Coefficient of variation across types (\%)}}\\")
w(r"Taxonomy & Anterior & Middle & Posterior & Talonavicular & Calcaneocuboid & Talocalcaneal\\\midrule")
def cv(idx, k):
    v = [CLS[k][i] for i in idx]
    return 100 * st.stdev(v) / st.mean(v)
for name, idx in [("Rozansky I--V", roz), ("Anatomy-based I--IV", ana), ("Rozansky I--IV (middle-facet variants)", list(range(1, 5)))]:
    w(name + " & " + " & ".join(f"{cv(idx, k):.1f}" for k in ["ant_max", "mid_max", "post_max", "tn_max", "cc_max", "tc_max"]) + r"\\")
w(r"\bottomrule\end{tabular}")
w(r"\par\vspace{1.2em}")
w(r"\begin{tabular}{@{}lrrrrr@{}}\toprule")
w(r"\multicolumn{6}{@{}l}{\emph{c, Peak stress as a percentage of the intact joint}}\\")
w(r"Model & Anterior & Middle & Posterior & Talonavicular & Calcaneocuboid\\\midrule")
for i in range(1, 11):
    vals = []
    for k in ["ant_max", "mid_max", "post_max", "tn_max", "cc_max"]:
        v = CLS[k][i]
        vals.append("--" if v is None else f"{100 * v / CLS[k][0]:.0f}")
    w(CLS_MODELS[i].replace("Roz", "Rozansky").replace("Fusion", "Complete fusion") + " & " + " & ".join(vals) + r"\\")
    if i in (5, 9):
        w(r"\addlinespace")
w(r"\bottomrule\end{tabular}")
w(r"\end{table}")
w("")

